import React, { useState, useEffect } from 'react';
import PlayerRow from './PlayerRow';
import ChampionsLeagueFooter from './ChampionsLeagueFooter';
import ChampionsLeagueHeader from './ChampionsLeagueHeader';

const ChampionsLeagueScorers = () => {
  const [champions, setChampions] = useState([]);
  const [detailPlayer, setDetailPlayer] = useState(null);
  const [activeView, setActiveView] = useState('home');
  const [loading, setLoading] = useState(true);
  const [jugadoresDetalle, setJugadoresDetalle] = useState([]);

  // Cargar datos de los máximos goleadores
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Cargar datos de goleadores desde top-champions-league-scorers.json
        const response = await fetch('/data/top-champions-league-scorers.json');
        const data = await response.json();

        // Cargar datos detallados de jugadores
        const responseDetalle = await fetch('/data/jugadores.json');
        const dataDetalle = await responseDetalle.json();
        setJugadoresDetalle(dataDetalle);

        // Si el archivo de goleadores está vacío, usar los datos detallados
        if (Array.isArray(data) && data.length === 0) {
          setChampions(dataDetalle);
        } else {
          // Mapear los datos del top-champions-league-scorers.json al formato esperado
          const mappedData = data.map(player => {
            return {
              position: player.position || "", 
              player: player.nombre || player.player || "",
              nationality: player.nacionalidad || player.nationality || "",
              birthdate: player.fecha_nacimiento || player.birthdate || "",
              goals: player.goles_totales || player.goals || 0,
              matches: player.partidos || player.matches || 0,
              finals: player.finales || player.finals || 0,
              titles: player.titulos || player.titles || 0,
              teams: player.equipos ? player.equipos.map(e => e.equipo || e) : player.teams || [],
              biography: player.biografia || player.biography || "",
              seasons: player.temporadas || player.seasons || []
            };
          });
          setChampions(mappedData);
        }

        setLoading(false);
      } catch (error) {
        console.error('Error loading data:', error);
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Función para mostrar detalles del jugador
  const showPlayerDetails = (player) => {
    setDetailPlayer(player);
    setActiveView('player-detail');
  };

  // Función para mostrar equipos del jugador
  const showPlayerTeams = (player) => {
    setDetailPlayer(player);
    setActiveView('player-teams');
  };

  // Función para mostrar temporadas del jugador
  const showPlayerSeasons = (player) => {
    setDetailPlayer(player);
    setActiveView('player-seasons');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center">
          <div className="w-32 h-32 mx-auto mb-6 rounded-xl shadow-lg p-2 border border-champions-gold/30 bg-champions-blue/80">
            <img 
              src="/images/logos/cc.png" 
              alt="Champions League Logo" 
              className="w-full h-full object-contain animate-pulse"
            />
          </div>
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-champions-gold mx-auto"></div>
          <p className="mt-4 text-lg text-white">
            <span className="champions-star">★</span> Cargando goleadores <span className="champions-star">★</span>
          </p>
        </div>
      </div>
    );
  }

  // Vista Principal - Lista de Goleadores
  const HomeView = () => {
    return (
      <div className="w-full max-w-6xl mx-auto px-4 py-8">
        <h2 className="text-3xl font-bold text-center mb-8 text-champions-blue">Máximos Goleadores de la UEFA Champions League</h2>

        <div className="bg-white shadow-lg rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-champions-blue">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Posición</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Jugador</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Equipo(s)</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Goles</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Partidos</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Finales</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-white uppercase tracking-wider">Títulos</th>
                </tr>
              </thead>
              <tbody>
                {champions.map((player) => (
                  <tr 
                    key={player.position}
                    className="hover:bg-blue-50 border-b border-gray-200 group"
                    onClick={() => showPlayerDetails(player)}
                  >
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {player.position}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="flex-shrink-0 h-10 w-10 bg-champions-blue rounded-full flex items-center justify-center text-white font-bold">
                          {player.player && player.player.substring(0, 2) || "??"}
                        </div>
                        <div className="ml-4">
                          <div className="text-sm font-medium text-gray-900">{player.player || "Desconocido"}</div>
                          <div className="text-sm text-gray-500">{player.nationality || "Desconocido"}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {player.teams && player.teams.join(', ') || "Desconocido"}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-champions-gold">
                      {player.goals || 0}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {player.matches || 0}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {player.finals || 0}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {player.titles || 0}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  // Vista de Detalles del Jugador
  const PlayerDetailView = () => {
    if (!detailPlayer) return null;

    return (
      <div className="w-full max-w-6xl mx-auto px-4 py-8">
        <div className="bg-white shadow-lg rounded-lg overflow-hidden">
          <div className="bg-champions-blue px-6 py-4">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-bold text-white">{detailPlayer.player || "Jugador"}</h3>
              <button 
                onClick={() => setActiveView('home')}
                className="bg-white text-champions-blue px-4 py-2 rounded font-bold hover:bg-gray-100"
              >
                Volver
              </button>
            </div>
          </div>

          <div className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="col-span-1">
                <div className="bg-gray-100 p-4 rounded-lg">
                  <h4 className="text-xl font-semibold mb-3 text-champions-blue">Información Personal</h4>
                  <p className="text-gray-600 mb-2"><span className="font-medium">Nacionalidad:</span> {detailPlayer.nationality || "Desconocida"}</p>
                  <p className="text-gray-600 mb-2"><span className="font-medium">Fecha de nacimiento:</span> {detailPlayer.birthdate || "Desconocida"}</p>
                  <p className="text-gray-600 mb-2"><span className="font-medium">Equipos:</span> {detailPlayer.teams && detailPlayer.teams.join(', ') || "Desconocido"}</p>
                </div>
              </div>

              <div className="col-span-1 md:col-span-2">
                <div className="bg-gray-100 p-4 rounded-lg h-full">
                  <h4 className="text-xl font-semibold mb-3 text-champions-blue">Biografía</h4>
                  <p className="text-gray-600">{detailPlayer.biography || "Información no disponible"}</p>
                </div>
              </div>
            </div>

            <div className="mt-8">
              <h4 className="text-xl font-semibold mb-3 text-champions-blue">Estadísticas en Champions League</h4>
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="bg-champions-blue text-white p-4 rounded-lg text-center">
                  <p className="text-3xl font-bold">{detailPlayer.goals || 0}</p>
                  <p className="text-sm uppercase">Goles</p>
                </div>
                <div className="bg-champions-blue text-white p-4 rounded-lg text-center">
                  <p className="text-3xl font-bold">{detailPlayer.matches || 0}</p>
                  <p className="text-sm uppercase">Partidos</p>
                </div>
                <div className="bg-champions-blue text-white p-4 rounded-lg text-center">
                  <p className="text-3xl font-bold">{detailPlayer.finals || 0}</p>
                  <p className="text-sm uppercase">Finales</p>
                </div>
                <div className="bg-champions-blue text-white p-4 rounded-lg text-center">
                  <p className="text-3xl font-bold">{detailPlayer.titles || 0}</p>
                  <p className="text-sm uppercase">Títulos</p>
                </div>
              </div>
            </div>

            <div className="mt-8 flex space-x-4">
              <button 
                onClick={() => showPlayerTeams(detailPlayer)}
                className="bg-champions-blue text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700 flex-1"
              >
                Ver Equipos
              </button>
              <button 
                onClick={() => showPlayerSeasons(detailPlayer)}
                className="bg-champions-blue text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700 flex-1"
              >
                Ver Temporadas
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Vista de Equipos del Jugador
  const PlayerTeamsView = () => {
    if (!detailPlayer) return null;

    // Obtener equipos de manera compatible con ambos formatos JSON
    let equipos = [];

    // Comprobar si los datos vienen en formato del top-champions-league-scorers.json
    if (detailPlayer.equipos && Array.isArray(detailPlayer.equipos)) {
      equipos = detailPlayer.equipos.map(equipo => ({
        equipo: equipo.equipo || "",
        goles: equipo.goles || 0,
        temporadas: equipo.temporadas || 0
      }));
    } 
    // Comprobar si los datos vienen en formato de jugadores.json
    else if (detailPlayer.teams && Array.isArray(detailPlayer.teams)) {
      // Si solo tenemos nombres de equipos, creamos objetos para cada uno
      equipos = detailPlayer.teams.map(team => {
        // Intentar encontrar estadísticas por equipo contando las temporadas
        let goles = 0;
        let temporadas = 0;

        if (detailPlayer.seasons && Array.isArray(detailPlayer.seasons)) {
          // Contar temporadas para este equipo
          const teamSeasons = detailPlayer.seasons.filter(s => s.club === team);
          temporadas = teamSeasons.length;

          // Sumar goles para este equipo
          goles = teamSeasons.reduce((sum, season) => sum + (season.goals || 0), 0);
        }

        return {
          equipo: team,
          goles: goles,
          temporadas: temporadas
        };
      });
    }

    return (
      <div className="w-full max-w-6xl mx-auto px-4 py-8">
        <div className="bg-white shadow-lg rounded-lg overflow-hidden">
          <div className="bg-champions-blue px-6 py-4">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-bold text-white">Equipos de {detailPlayer.player || detailPlayer.nombre || "Jugador"}</h3>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setActiveView('player-detail')}
                  className="bg-white text-champions-blue px-4 py-2 rounded font-bold hover:bg-gray-100"
                >
                  Volver al Perfil
                </button>
                <button 
                  onClick={() => setActiveView('home')}
                  className="bg-white text-champions-blue px-4 py-2 rounded font-bold hover:bg-gray-100"
                >
                  Inicio
                </button>
              </div>
            </div>
          </div>

          <div className="p-6">
            {equipos && equipos.length > 0 ? (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {equipos.map((equipo, index) => (
                    <div key={index} className="bg-gray-100 p-4 rounded-lg">
                      <h4 className="text-xl font-semibold mb-3 text-champions-blue">{equipo.equipo || "Equipo"}</h4>
                      <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white p-3 rounded text-center">
                          <p className="text-3xl font-bold text-champions-gold">{equipo.goles || 0}</p>
                          <p className="text-sm uppercase">Goles</p>
                        </div>
                        <div className="bg-white p-3 rounded text-center">
                          <p className="text-3xl font-bold text-champions-blue">{equipo.temporadas || 0}</p>
                          <p className="text-sm uppercase">Temporadas</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="mt-8">
                  <h4 className="text-xl font-semibold mb-3 text-champions-blue">Rendimiento por Equipo</h4>
                  <div className="bg-gray-100 p-4 rounded-lg">
                    <div className="w-full h-16 bg-gray-200 rounded-full flex overflow-hidden">
                      {equipos.map((equipo, index) => {
                        const totalGoles = detailPlayer.goals || detailPlayer.goles_totales || 1;
                        const porcentaje = (equipo.goles / totalGoles) * 100;
                        const colores = ["bg-champions-gold", "bg-champions-blue", "bg-green-500", "bg-purple-500"];
                        return (
                          <div 
                            key={index}
                            className={`${colores[index % colores.length]} h-full`}
                            style={{ width: `${porcentaje}%` }}
                            title={`${equipo.equipo || "Equipo"}: ${equipo.goles || 0} goles (${porcentaje.toFixed(1)}%)`}
                          ></div>
                        );
                      })}
                    </div>
                    <div className="mt-2 flex flex-wrap">
                      {equipos.map((equipo, index) => {
                        const totalGoles = detailPlayer.goals || detailPlayer.goles_totales || 1;
                        const porcentaje = (equipo.goles / totalGoles) * 100;
                        const colores = ["bg-champions-gold", "bg-champions-blue", "bg-green-500", "bg-purple-500"];
                        return (
                          <div key={index} className="flex items-center mr-4 mb-2">
                            <div className={`w-3 h-3 ${colores[index % colores.length]} rounded-full mr-1`}></div>
                            <span className="text-sm text-gray-600">{equipo.equipo || "Equipo"} ({porcentaje.toFixed(1)}%)</span>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="p-8 text-center">
                <p className="text-gray-500">No hay información disponible sobre los equipos de este jugador.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  // Vista de Temporadas del Jugador
  const PlayerSeasonsView = () => {
    if (!detailPlayer) return null;

    // Obtener temporadas de manera compatible con ambos formatos JSON
    let temporadas = [];

    // Comprobar si los datos vienen en formato del top-champions-league-scorers.json
    if (detailPlayer.temporadas && Array.isArray(detailPlayer.temporadas)) {
      temporadas = detailPlayer.temporadas;
    } 
    // Comprobar si los datos vienen en formato de jugadores.json
    else if (detailPlayer.seasons && Array.isArray(detailPlayer.seasons)) {
      temporadas = detailPlayer.seasons.map(season => ({
        temporada: season.season || "",
        equipo: season.club || "",
        goles: season.goals || 0,
        partidos: season.matches || 0,
        asistencias: season.assists || 0,
        titulo: season.title || false
      }));
    }

    // Encontrar la mejor temporada (más goles)
    const mejorTemporada = temporadas && temporadas.length > 0 ? 
      temporadas.reduce((mejor, actual) => 
        (mejor.goles || 0) > (actual.goles || 0) ? mejor : actual, 
        { goles: 0 }
      ) : null;

    return (
      <div className="w-full max-w-6xl mx-auto px-4 py-8">
        <div className="bg-white shadow-lg rounded-lg overflow-hidden">
          <div className="bg-champions-blue px-6 py-4">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-bold text-white">Temporadas de {detailPlayer.player || detailPlayer.nombre || "Jugador"}</h3>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setActiveView('player-detail')}
                  className="bg-white text-champions-blue px-4 py-2 rounded font-bold hover:bg-gray-100"
                >
                  Volver al Perfil
                </button>
                <button 
                  onClick={() => setActiveView('home')}
                  className="bg-white text-champions-blue px-4 py-2 rounded font-bold hover:bg-gray-100"
                >
                  Inicio
                </button>
              </div>
            </div>
          </div>

          <div className="p-6">
            {mejorTemporada && mejorTemporada.goles > 0 && (
              <div className="mb-8">
                <h4 className="text-xl font-semibold mb-3 text-champions-blue">Mejor Temporada</h4>
                <div className="bg-champions-gold bg-opacity-20 p-4 rounded-lg border-l-4 border-champions-gold">
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="col-span-1">
                      <p className="text-lg font-bold">{mejorTemporada.temporada || mejorTemporada.season || "Desconocida"}</p>
                      <p className="text-sm text-gray-600">{mejorTemporada.equipo || mejorTemporada.club || "Desconocido"}</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-gold">{mejorTemporada.goles || mejorTemporada.goals || 0}</p>
                      <p className="text-sm text-gray-600">Goles</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-blue">{mejorTemporada.partidos || mejorTemporada.matches || 0}</p>
                      <p className="text-sm text-gray-600">Partidos</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-green-500">{mejorTemporada.asistencias || mejorTemporada.assists || 0}</p>
                      <p className="text-sm text-gray-600">Asistencias</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Resumen de Rendimiento General */}
            {temporadas && temporadas.length > 0 && (
              <div className="mb-8">
                <h4 className="text-xl font-semibold mb-3 text-champions-blue">Resumen de Rendimiento</h4>
                <div className="bg-champions-blue bg-opacity-10 p-4 rounded-lg">
                  <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-blue">
                        {temporadas.reduce((total, temp) => total + (parseInt(temp.goles || temp.goals || 0)), 0)}
                      </p>
                      <p className="text-sm text-gray-600">Goles Totales</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-blue">
                        {temporadas.reduce((total, temp) => total + (parseInt(temp.partidos || temp.matches || 0)), 0)}
                      </p>
                      <p className="text-sm text-gray-600">Partidos Totales</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-blue">
                        {temporadas.reduce((total, temp) => total + (parseInt(temp.asistencias || temp.assists || 0)), 0)}
                      </p>
                      <p className="text-sm text-gray-600">Asistencias Totales</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-champions-gold">
                        {temporadas.filter(temp => temp.titulo || temp.title).length}
                      </p>
                      <p className="text-sm text-gray-600">Títulos Ganados</p>
                    </div>
                    <div className="col-span-1 text-center">
                      <p className="text-3xl font-bold text-green-500">
                        {(temporadas.reduce((total, temp) => total + (parseInt(temp.goles || temp.goals || 0)), 0) / 
                          temporadas.reduce((total, temp) => total + (parseInt(temp.partidos || temp.matches || 0)), 0)).toFixed(2)}
                      </p>
                      <p className="text-sm text-gray-600">Goles por Partido</p>
                    </div>
                  </div>

                  {temporadas.filter(temp => temp.titulo || temp.title).length > 0 && (
                    <div className="mt-4 p-3 bg-champions-gold bg-opacity-10 rounded-lg">
                      <h5 className="text-lg font-semibold text-champions-gold mb-2">Éxitos en Champions League</h5>
                      <p className="text-gray-700">
                        {detailPlayer.player || detailPlayer.nombre || "El jugador"} ha ganado la Champions League 
                        {temporadas.filter(temp => temp.titulo || temp.title).length > 1 ? 
                          ` en ${temporadas.filter(temp => temp.titulo || temp.title).length} ocasiones` : 
                          " una vez"}.
                        Las temporadas ganadoras fueron: {temporadas
                          .filter(temp => temp.titulo || temp.title)
                          .map(temp => temp.temporada || temp.season)
                          .join(", ")}.
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {temporadas && temporadas.length > 0 ? (
              <div>
                <h4 className="text-xl font-semibold mb-3 text-champions-blue">Todas las Temporadas</h4>
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-100">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Temporada</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Equipo</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Partidos</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Goles</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Asistencias</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Título</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {temporadas.map((temp, index) => (
                        <tr key={index} className={temp.titulo || temp.title ? "bg-green-50" : ""}>
                          <td className="px-4 py-3 whitespace-nowrap text-sm font-medium text-gray-900">
                            {temp.temporada || temp.season || "Desconocida"}
                          </td>
                          <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                            {temp.equipo || temp.club || "Desconocido"}
                          </td>
                          <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                            {temp.partidos || temp.matches || 0}
                          </td>
                          <td className="px-4 py-3 whitespace-nowrap text-sm font-medium text-champions-gold">
                            {temp.goles || temp.goals || 0}
                          </td>
                          <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                            {temp.asistencias || temp.assists || 0}
                          </td>
                          <td className="px-4 py-3 whitespace-nowrap text-sm">
                            {(temp.titulo || temp.title) ? (
                              <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                                Campeón
                              </span>
                            ) : "-"}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ) : (
              <div className="p-8 text-center">
                <p className="text-gray-500">No hay información disponible sobre las temporadas de este jugador.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  let activeComponent;
  switch (activeView) {
    case 'home':
      activeComponent = <HomeView />;
      break;
    case 'player-detail':
      activeComponent = <PlayerDetailView />;
      break;
    case 'player-teams':
      activeComponent = <PlayerTeamsView />;
      break;
    case 'player-seasons':
      activeComponent = <PlayerSeasonsView />;
      break;
    default:
      activeComponent = <HomeView />;
  }

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      <header className="bg-champions-blue text-white py-4 shadow-md">
        <div className="max-w-6xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center">
            <img 
              src="/images/logos/cc.png" 
              alt="Champions League Logo" 
              className="w-10 h-10 mr-3"
            />
            <h1 className="text-xl font-bold">UEFA Champions League - Máximos Goleadores</h1>
          </div>
        </div>
      </header>

      {activeComponent}

      <footer className="bg-gray-800 text-white py-4 mt-auto">
        <div className="max-w-6xl mx-auto px-4 text-center">
          <p>&copy; {new Date().getFullYear()} UEFA Champions League - Estadísticas Históricas</p>
        </div>
      </footer>
    </div>
  );
};

export default ChampionsLeagueScorers;
